INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63083445', 63083445, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Banten', 'IMPLANT 2 BATANG', 'Barang', 'E-Purchasing', 'Banten, Serang (Kota)', 14524218000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 87390, SET, @ 166200 )', '1. IMPLANT 2 BATANG ( 87390, SET, @ 166200 );', 'a.Umum : a) Kandungan: Implan terdiri dari dua jenis yaitu (1) 1 batang Berisi 68 mg Etonogestrel atau 160 mg Levonorgestrel yang terdapat di dalam aplikator preloaded; atau (2) 2 batang Batang elastic silicon tube yang masing-masing berisi 75 mg Levonorgestrel yang terdapat didalam jarum trokar/inserter sekali pakai (disposable) terdiri dari: (a) Turbular Metal Needle (b) Surgical Blade b.Sertifikasi mutu: (1) Nomor Izin Edar (NIE) Mempunyai Nomor Izin Edar (NIE) dari BPOMRI untuk obat dan atau Nomor Izin Edar (NIE) dari Kemenkes untuk alat kesehatan yang masih berlaku. (2) Cara Pembuatan Obat yang Baik (CPOB) Mempunyai sertifikat CPOB dari BPOM-RI dan masih berlaku . (3) Cara Distribusi Obat yang Baik (CDOB) - 27 - Mempunyai sertifikat CDOB dari BPOM-RI dan masih berlaku bagi Pedagang Besar Farmasi (PBF). (4) Certificate Of Analysis (CoA) Memiliki CoA yang memenuhi syarat. c.Parameter uji : Sesuai dengan produk yang didaftarkan ke BPOM RI. Masa kadaluarsa: Paling sedikit 2.5 (dua koma lima) tahun sejak diterima di gudang Pusat/Perwakilan BKKBN Provinsi Kemasan Implan : Informasi produk dan penandaan pada kemasan mengikuti persyaratan dalam Nomor Ijin Edar produk Implan dari BPOM dan informasi tambahan dari BKKBN sebagai berikut : a.Individual Pack (1) Pada setiap individual pack harus tercantum nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun) (2) Pada setiap individual pack tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (3) Pada setiap individual pack harus tercantum tulisan “Kementerian Kependudukan dan Pembangunan Kekuarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan tulisan “Tidak Diperjualbelikan” dengan warna merah. (4) Ketentuan sebagaimana no (3) dikecualikan pada: (i)Produk Impor yang sudah beredar di Indonesia dan pengemasannya dilakukan di negara asal (ii)Tidak tersedia ruang yang memadai (5) Jumlah individual pack yang dimasukkan kedalam inner box disesuaikan dengan kemasan yang tercantum dalam NIE. b.Inner Box (Box Kecil) (1) Setiap inner box dilengkapi dengan petunjuk pemakaian dalam bahasa Indonesia, 1 copy untuk setiap Implan. (2) Pada setiap inner box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (3) Setiap inner box tertulis nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun) (4) Pada inner box harus tercantum “Kementerian Kependudukan dan Pembangunan Kekuarga/BKKBN APBN Tahun Anggaran 2026”” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. (5) Jumlah inner box yang dimasukkan ke dalam outer box (box besar) disesuaikan dengan kemasan yang tercantum dalam NIE. c.Outer Box (Box Besar) (1) Pada setiap outer box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (2) Pada outer box tercantum nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun) tertulis pada dua sisi. (3) Setiap satu outer box tercantum tulisan ”Kementerian Kependudukan dan Pembangunan Kekuarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan tulisan “Tidak diperjualbelikan” dengan warna merah. (4) Ketebalan karton outer box menyesuaikan dengan jenis dan berat produk agar dapat terjamin keamanan, mutu, dan manfaat produk', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 553340);
