INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63083444', 63083444, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Banten', 'IUD Post Partum', 'Barang', 'E-Purchasing', 'Banten, Serang (Kota)', 67925000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1625, SET, @ 41800 )', '1. IUD Post Partum ( 1625, SET, @ 41800 );', 'a.Kelengkapan isi per unit 1)1 buah label Stiker Belakang Post Partum Tcu 380A 2)1 Unit Post Partum IUD Tcu 380 A 3)1 Buah tabung long inserter diameter 0,8 cm dan panjang long inserter 35 cm 4)1 buah flangewarna biru b.Sertifikasi Mutu 1)Memiliki Nomor Izin Edar (NIE) dari Kemenkes dan Masih Berlaku 2)Memiliki Sertifikat Cara Pembuatan Alat Kesehatan Yang Baik (CPAKB) dari Kemenkes dan masih berlaku 3)Memiliki Sertifikat Cara Distribusi Alat Kesehatan yang Baik (CDAKB) dari Kemenkes dan Masih berlaku bagi Penyalur Alat Kesehatan 4)Memiliki CoA (Certificate of Analysis) 5)Parameter Uji sesuai Produk yang didaftarkan ke Kemenkes RI 6)Batas kadaluarsa Minimal 5 (lima) tahun sejak dilakukan penyerahan barang di gudang perwakilan BKKBN Provinsi Banten dan atau tahun produksi yang disesuaikan dengan tahun pengadaan Pelabelan/penandaan kemasan IUD Post Partum mengikuti peraturan perundang-undangan yang berlaku dari kementrian Kesehatan RI dan informasi tambahan dari BKKBN sebagai berikut: A.Individual Pack (Unit) 1)Setiap unit IUD Post Partum steril dibungkus dalam plastik transparant. 2)Pada setiap individual pack harus tercantum nomor batch, nomor registrasi, tahun produksi dan batas kadaluarsa (bulan, tahun). 3)Pada setiap individual pack tercantum nama produk yang disesuaikan nama produk di Dokumen Izin Edar 4)Pada setiap Individual pack tercantum tulisan “Kementerian Kependudukan dan Pembangunan Kekuarga/BKKBN APBN Tahun Anggaran 2026”dengan warna Hitam/Biru dan “Tidak diperjualbelikan” dengan warna merah 5)Ketentuan sebagaimana no (4) dikecualikan pada: (vii)Produk Impor yang sudah beredar di Indonesia dan pengemasannya dilakukan di negara asal (viii)Tidak tersedia ruang yang memadai B.Inner Box (Box Kecil) 1)Setiap inner box dilengkapi dengan petunjuk pemakaian dalam bahasa indonesia, 1 copy untuk setiap buah. 2)Pada setiap inner box tercantum nama produk yang disesuaikan nama produk di Dokumen Izin Edar 3)Pada setiap inner box terdapat tulisan nomor batch, nomor registrasi, tahun produksi dan batas kadaluarsa (bulan, tahun). 4)Pada setiap inner box harus tercantum tulisan “Kementerian Kependudukan dan Pembangunan Kekuarga/BKKBN APBN Tahun Anggaran 2026” dengan warna Hitam/Biru dan “Tidak diperjualbelikan” dengan warna merah 5)Jumlah Inner box yang dimasukan kedalam outter box (Box besar) disesuaikan dengan kemasan yang sesuai dengan NIE C.Outer Box (Box Besar) 1)Pada setiap outer box tercantum tercantum nama produk yang disesuaikan nama produk di Dokumen Izin Edar 2)Pada outer box tertulis nomor batch, nomor registrasi, tahun produksi dan batas kadaluarsa (bulan, tahun). 3)Pada setiap outer box harus tercantum tulisan “Kementerian Kependudukan dan Pembangunan Kekuarga/BKKBN APBN Tahun Anggaran 2026” dengan warna Hitam/Biru dan “Tidak diperjualbelikan” dengan warna merah Ketebalan karton outer box menyesuaikan dengan jenis dan berat produk agar dapat terjamin keamanan, mutu dan manfaat produk', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 554936);
