INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63083453', 63083453, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Banten', 'BMHP ADS IMPLANT', 'Barang', 'E-Purchasing', 'Banten, Serang (Kota)', 31084000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 20723, BUAH, @ 1500 )', '1. BMHP ADS IMPLANT ( 20723, BUAH, @ 1500 );', 'Spesifikasi 1) Spesifikasi Umum a). Disposable Syringe (Alat Suntik sekali pakai) (1) Kapasitas Volume : 3.0 ml (2) Ukuran Jarum : 23 G x 1 ¼” (3) Parameter uji : Sesuai dengan produk yang didaftarkan ke Kementerian Kesehatan RI. b). Registrasi Memiliki Nomor Ijin Edar (NIE) dari Kementerian Kesehatan RI dan masih berlaku. c). Masa Kedaluwarsa Minimal 3 (tiga) tahun sejak dilakukan penyerahan barang di gudang Pusat/Perwakilan BKKBN Provinsi Banten dan atau tahun produksi yang disesuaikan dengan tahun pengadaan Pelabelan/penandaan kemasan Disposable Syringe mengikuti peraturan perundang-undangan yang berlaku dan informasi tambahan yang ditetapkan BKKBN sebagai berikut: a). Individual pack : (1) Setiap alat suntik sekali pakai berikut jarum dikemas ke dalam plastik steril transparant. (2) Pada setiap individual pack harus tercantum nomor bacth, nomor registrasi, tahun produksi dan batas kadaluarsa (tanggal, bulan, tahun) (3) Pada setiap individual pack tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (4) Setiap individual pack tercantum tulisan “BKKBN APBN Tahun Anggaran 2025” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. b). Inner box (boks kecil). (1) Pada setiap inner box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (2) Pada inner box tertulis nomor batch, nomor registrasi, tahun produksi dan tahun kadaluarsa (tanggal, bulan, tahun) dengan warna biru/hitam. (3) Setiap inner box tercantum tulisan “Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna m (4) Pada setiap inner box dilengkapi dengan petunjuk pemakaian dalam Bahasa Indonesia, 1 copy untuk setiap inner box. c). Outer box (1) Pada setiap outer box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (2) Pada outer box tertulis nomor batch, nomor registrasi, tahun produksi dan batas kadaluarsa (tanggal, bulan, tahun), dengan warna biru/hitam. (3) Setiap outer box tercantum tulisan “Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. (4) Ketebalan karton outer box menyesuaikan dengan jenis dan berat produk agar dapat terjamin keamanan, mutu, dan manfaat produk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 557073);
